"""FLUX.2 [klein] stills, generated by diffusers in a separate interpreter.

The app never imports torch: this module runs in the image virtual environment
(`image-venv`, or any interpreter with torch + diffusers) and writes one PNG.
Keeping it out of the server process means a 8 GB model load cannot take the
reader down with it, and the GPU stack stays replaceable.

    python -m murmur.fluxgen --prompt "..." --width 1920 --height 1080 \
        --seed 7 --steps 4 --out still.png [--reference prev.png --strength 0.6]
"""
from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

MODEL_ID = os.environ.get("MURMUR_FLUX_MODEL", "black-forest-labs/FLUX.2-klein-4B")


def _device(torch) -> str:
    if torch.cuda.is_available():
        return "cuda"
    mps = getattr(torch.backends, "mps", None)
    if mps is not None and mps.is_available():
        return "mps"
    return "cpu"


def _load(torch, device: str, offload: bool):
    from diffusers import Flux2KleinPipeline

    dtype = torch.bfloat16 if device != "cpu" else torch.float32
    pipe = Flux2KleinPipeline.from_pretrained(MODEL_ID, torch_dtype=dtype)
    if offload:
        # Text encoder and transformer take turns on the card; slower, but it
        # fits where a full residency does not.
        pipe.enable_model_cpu_offload()
    else:
        pipe = pipe.to(device)
    pipe.set_progress_bar_config(disable=True)
    return pipe


def generate(
    prompt: str,
    out_path: Path,
    width: int,
    height: int,
    seed: int,
    steps: int = 4,
    reference: Path | None = None,
    strength: float = 0.55,
    guidance: float = 1.0,
) -> None:
    import torch
    from PIL import Image

    device = _device(torch)
    if device == "cpu" and not os.environ.get("MURMUR_ALLOW_CPU_FILM"):
        raise SystemExit("no GPU is visible to torch; refusing to paint on the CPU")

    width = max(256, int(round(width / 16)) * 16)
    height = max(256, int(round(height / 16)) * 16)

    offload = os.environ.get("MURMUR_FLUX_OFFLOAD") == "1"
    try:
        pipe = _load(torch, device, offload)
    except RuntimeError as exc:
        if "out of memory" not in str(exc).lower():
            raise
        torch.cuda.empty_cache()
        pipe = _load(torch, device, True)

    kwargs = {
        "prompt": prompt,
        "width": width,
        "height": height,
        "num_inference_steps": int(steps),
        "guidance_scale": float(guidance),
        "generator": torch.Generator(device=device if not offload else "cpu").manual_seed(int(seed)),
    }
    if reference is not None and Path(reference).exists():
        kwargs["image"] = Image.open(reference).convert("RGB").resize((width, height))
        kwargs["strength"] = float(strength)

    try:
        image = pipe(**kwargs).images[0]
    except TypeError:
        # Older pipelines may not take strength; refine without it.
        kwargs.pop("strength", None)
        image = pipe(**kwargs).images[0]

    out_path.parent.mkdir(parents=True, exist_ok=True)
    image.save(out_path, format="PNG")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="murmur.fluxgen")
    parser.add_argument("--prompt", required=True)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--width", type=int, default=1280)
    parser.add_argument("--height", type=int, default=720)
    parser.add_argument("--seed", type=int, default=1)
    parser.add_argument("--steps", type=int, default=4)
    parser.add_argument("--guidance", type=float, default=1.0)
    parser.add_argument("--reference", type=Path, default=None)
    parser.add_argument("--strength", type=float, default=0.55)
    args = parser.parse_args(argv)

    generate(
        args.prompt, args.out, args.width, args.height, args.seed,
        steps=args.steps, reference=args.reference, strength=args.strength,
        guidance=args.guidance,
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
